import tempfile


class _NoCallSession:
    def get(self, *args, **kwargs):
        raise AssertionError("no network call expected")

with tempfile.TemporaryDirectory() as td:
    conn = connect_db(Path(td) / "t.sqlite")
    init_schema(conn)

    def _queries(_s, _e):
        return []

    def _extract(_tx, _entity):
        return []

    def _insert(_conn, rows):
        assert rows == []
        return 0

    stats = _scan_windows_generic(
        conn,
        _NoCallSession(),
        entity_type="node",
        entity_id="14",
        event_kind="reward",
        start_height=10,
        end_height=9,
        window_size=1000,
        nyx_tx_rest=DEFAULT_NYX_TX_REST,
        queries_for_window=_queries,
        extract_rows=_extract,
        insert_rows=_insert,
        force=False,
        page_size=100,
        max_pages=5,
        timeout=5,
        logger=logging.getLogger("test"),
    )
    assert stats["windows"] == 0
    assert stats["errors"] == 0

